import{_ as e,X as i,Y as a,a1 as r,a0 as n}from"./framework-68dd73a2.js";const l={},t=n(`<h1 id="地狱历险记" tabindex="-1"><a class="header-anchor" href="#地狱历险记" aria-hidden="true">#</a> 地狱历险记</h1><div class="hint-container warning"><p class="hint-container-title">注意</p><p>本博文仅供学术研究和交流参考，严禁将其用于商业用途。如因违规使用产生的任何法律问题，使用者需自行负责。</p></div><hr><h3 id="分割线1" tabindex="-1"><a class="header-anchor" href="#分割线1" aria-hidden="true">#</a> 分割线1</h3><hr><p>2024年06月11日经过慎重的思考我选择加入了世界排名前前26位的企业，虽然有点类似于“全聚德”里的鸭子，但好歹也算是加入了一个大企业了！相比外面那些企业，这可能是我这一生中所能进入到的醉大的企业了。</p><hr><h3 id="理想中的企业的期待" tabindex="-1"><a class="header-anchor" href="#理想中的企业的期待" aria-hidden="true">#</a> 理想中的企业的期待</h3><hr><p>它满足了我对于自己未来的几个期待：</p><ol><li>不会轻易倒闭！</li><li>不会轻易失业！</li><li>不会饿着！</li><li>不会渴着!</li><li>有地方上厕所!</li><li>有地方住！</li><li>有公积金！</li><li>有七险!</li><li>还有一点点薪水!</li></ol><p>这几乎是我能找到的完美企业了，虽然做不成我想要的互联网行业，但我能怎么办呢，必须得进行取舍。但同时缺点也非常明显，按严重程度进行排序：</p><ol><li><strong>每天十个小时的有效工作时间</strong>，但需要投入至少十三个小时在工上，才能产出十个小时的有效工作时间！</li><li><strong>没有双休</strong>,当然这点薪水来说，大家都没有什么消费能力的，也不会期待周末去愉快玩耍这种事的！</li><li><strong>一月一次通宵班</strong>,人类诞生以来，也就我所处的时代需要通宵上班的，古人为奴也未有过，但没办法，这是必须要进行的交换！</li><li><strong>三十多慢性化学毒气伤害</strong>！这个很无语了，也没有解，谁叫我出生在&quot;精神病院&quot;呢，连无产阶级也算不上!</li><li><strong>底层的厮杀非常激烈！！！</strong>，因为它是无门槛的招聘，里面的人层次各不相同，底层的无规则无限制格斗非常可怕！</li></ol><hr><h3 id="我理想中的生活" tabindex="-1"><a class="header-anchor" href="#我理想中的生活" aria-hidden="true">#</a> 我理想中的生活</h3><hr><ol><li>无人欺(欺负/欺骗)</li><li>无人敢欺(欺负/欺骗)</li><li>脱离奴籍,还清被生下来欠国家的五百万人民币的欠款做一个真正的人!</li><li>逆天改命，单开族谱！做一姓氏的创始人!!!!</li></ol><hr><h3 id="这企业目前的收入" tabindex="-1"><a class="header-anchor" href="#这企业目前的收入" aria-hidden="true">#</a> 这企业目前的收入</h3><hr><p>目前是 2000 人民币的底薪，按21.75天作为计算：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>0.01/(2000/21.75/8/60/60) = 3.132000000000027
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>也就是说每秒钟的收入是 0.003元的收入,大概每呼吸每4秒钟毒气就可以收入<strong>一分钱</strong>！</p><p>如果按每月30天的标准时间计算，可以得出，每呼吸13秒就可以得到一分钱！</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>0.01/(2000/30/24/60/60) = 12.96
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><hr><h3 id="分割线" tabindex="-1"><a class="header-anchor" href="#分割线" aria-hidden="true">#</a> 分割线</h3><hr><div class="hint-container info"><p class="hint-container-title">相关信息</p><p><strong>以上就是我关于 <em>地狱历险记</em> 知识点的整理与总结的全部内容，希望对你有帮助。。。。。。。</strong></p></div>`,29);function d(s,o){return i(),a("div",null,[r(" more "),t])}const c=e(l,[["render",d],["__file","education19.html.vue"]]);export{c as default};
